{"code": "# 检查网关配置加载逻辑
import sys
sys.path.insert(0, '/opt/hermes/gateway')

from config import GatewayConfig

# 读取 config.yaml
import yaml
with open('/opt/data/config.yaml', 'r') as f:
    yaml_cfg = yaml.safe_load(f)

# 读取 gateway.json
import json
with open('/opt/data/gateway.json', 'r') as f:
    gw_cfg = json.load(f)

# 合并配置
gw_data = gw_cfg.copy()
yaml_platforms = yaml_cfg.get("platforms")
if isinstance(yaml_platforms, dict):
    platforms_data = gw_data.setdefault("platforms", {})
    if not isinstance(platforms_data, dict):
        platforms_data = {}
        gw_data["platforms"] = platforms_data
    for plat_name, plat_block in yaml_platforms.items():
        if not isinstance(plat_block, dict):
            continue
        existing = platforms_data.get(plat_name, {})
        if not isinstance(existing, dict):
            existing = {}
        merged_extra = {**existing.get("extra", {}), **plat_block.get("extra", {})}
        merged = {**existing, **plat_block}
        if merged_extra:
            merged["extra"] = merged_extra
        platforms_data[plat_name] = merged

print("Merged platforms config:")
print(json.dumps(gw_data.get("platforms", {}), indent=2))"}

